const texts={"fr":{"reserved":"Offer for HR Valais members","eyebrow":"Simplify your professional day","h1":"Discover AI, simply.","h2":"Try before you subscribe.","intro":"AI assistants for everyday tasks and SwissNote to turn your meetings into structured minutes and reports.","try":"Start my 7-day trial","trial":"7-day trial","credit":"CHF 5.– in free AI credit","hosting":"AI hosted in Switzerland or Europe","demos":"Discover the solutions in video","demoIntro":"Two demonstrations to explore what the platform can do.","platform":"IA Express — HR Valais","platformText":"Writing, analysis, research and professional assistants: discover how to save time every day.","swiss":"SwissNote — Minutes and reports","swissText":"Turn meetings and recordings into structured minutes and reports.","video":"Demonstration video to be added","pricing":"A simple and transparent offer","subscription":"HR Valais subscription","month":"/ month","quarter":"CHF 30.– billed every 3 months.","features":["Access to the IA Express platform","AI assistants for professional tasks","AI usage paid separately through a deposit"],"usage":"Usage to suit your needs","usageTitle":"You choose your deposit","usageText":"CHF 5.–, 10.–, 20.–, 50.– or another amount of your choice. Credit is added once payment is received.","costs":["AI assistants: generally a few centimes per use, depending on the task and model","SwissNote: approximately CHF 1.50 per set of minutes","Balance tracking and a personal alert threshold in your account"],"privacy":"Privacy and professional use","privacyTitle":"Keep control of your data","privacyText":"The AI models offered are hosted in Switzerland or Europe, depending on the selected provider. Use non-anonymised data only with approval from your responsible manager and in accordance with your organisation’s and provider’s rules.","technical":"IA Express technical information","technicalText":"A browser-based AI assistant platform, a personal space to monitor usage and SwissNote for meeting minutes and reports. Providers and available features depend on your organisation’s configuration.","ready":"Try it free for 7 days","readyText":"CHF 5.– in free usage credit. The trial ends after 7 days or when the credit is used up. No deposit is needed to start.","footer":"IA Express — IA Solutions Sàrl · HR Valais offer"},"de":{"reserved":"Angebot für Mitglieder von HR Valais","eyebrow":"Ihr Berufsalltag, einfacher","h1":"KI einfach entdecken.","h2":"Vor dem Abonnieren ausprobieren.","intro":"KI-Assistenten für Ihre täglichen Aufgaben und SwissNote für strukturierte Sitzungsprotokolle und Berichte.","try":"7 Tage kostenlos testen","trial":"7 Tage testen","credit":"CHF 5.– KI-Startguthaben","hosting":"KI in der Schweiz oder Europa gehostet","demos":"Entdecken Sie die Lösungen im Video","demoIntro":"Zwei Demonstrationen zeigen Ihnen die Möglichkeiten der Plattform.","platform":"IA Express — HR Valais","platformText":"Texte verfassen, analysieren und recherchieren: entdecken Sie die Assistenten für Ihren Berufsalltag.","swiss":"SwissNote — Protokolle und Berichte","swissText":"Verwandeln Sie Besprechungen und Aufnahmen in strukturierte Protokolle und Berichte.","video":"Demonstrationsvideo wird noch eingebunden","pricing":"Ein einfaches und transparentes Angebot","subscription":"HR-Valais-Abonnement","month":"/ Monat","quarter":"CHF 30.– werden alle 3 Monate in Rechnung gestellt.","features":["Zugang zur Plattform IA Express","KI-Assistenten für berufliche Aufgaben","KI-Verbrauch wird separat als Guthaben bezahlt"],"usage":"Verbrauch nach Ihrem Bedarf","usageTitle":"Sie wählen Ihr Guthaben","usageText":"CHF 5.–, 10.–, 20.–, 50.– oder ein anderer Betrag Ihrer Wahl. Die Gutschrift erfolgt nach Zahlungseingang.","costs":["KI-Assistenten: in der Regel wenige Rappen je Nutzung, abhängig von Aufgabe und Modell","SwissNote: etwa CHF 1.50 pro Protokoll","Guthabenübersicht und persönliche Warnschwelle in Ihrem Konto"],"privacy":"Vertraulichkeit und berufliche Nutzung","privacyTitle":"Behalten Sie die Kontrolle über Ihre Daten","privacyText":"Die angebotenen KI-Modelle werden je nach Anbieter in der Schweiz oder Europa gehostet. Verwenden Sie nicht anonymisierte Daten nur mit Genehmigung Ihrer verantwortlichen Person und gemäss den Regeln Ihrer Organisation und des Anbieters.","technical":"Technische Informationen zu IA Express","technicalText":"Eine im Browser zugängliche Plattform mit KI-Assistenten, einem persönlichen Bereich zur Verbrauchskontrolle und SwissNote für Protokolle und Berichte. Anbieter und Funktionen hängen von der Konfiguration Ihrer Organisation ab.","ready":"7 Tage kostenlos ausprobieren","readyText":"CHF 5.– Verbrauchsguthaben inklusive. Die Testphase endet nach 7 Tagen oder wenn das Guthaben aufgebraucht ist. Keine Vorauszahlung zum Start nötig.","footer":"IA Express — IA Solutions Sàrl · Angebot HR Valais"},"en":{"reserved":"HR Valais","eyebrow":"Votre quotidien professionnel, simplifié","h1":"Découvrez l’IA, simplement.","h2":"Essayez avant de vous abonner.","intro":"Des assistants IA pour vos tâches quotidiennes et SwissNote pour transformer vos réunions en procès-verbaux et rapports structurés.","try":"Commencer mon essai de 7 jours","trial":"7 jours d’essai","credit":"CHF 5.– de crédit IA offert","hosting":"IA hébergées en Suisse ou en Europe","demos":"Découvrez les solutions en vidéo","demoIntro":"Deux démonstrations pour comprendre les possibilités de la plateforme.","platform":"IA Express — HR Valais","platformText":"Rédaction, analyse, recherche et assistants métier : découvrez comment gagner du temps au quotidien.","swiss":"SwissNote — PV et rapports","swissText":"Transformez vos réunions et vos enregistrements en comptes rendus et rapports structurés.","video":"Vidéo de démonstration à intégrer","pricing":"Une offre simple et transparente","subscription":"Abonnement HR Valais","month":"/ mois","quarter":"CHF 30.– facturés tous les 3 mois.","features":["Accès à la plateforme IA Express","Assistants IA pour vos tâches professionnelles","Consommation IA payée séparément par acompte"],"usage":"Consommation selon vos besoins","usageTitle":"Vous choisissez votre acompte","usageText":"CHF 5.–, 10.–, 20.–, 50.– ou un autre montant de votre choix. Le crédit est ajouté après réception du paiement.","costs":["Assistants IA : généralement quelques centimes par utilisation, selon la tâche et le modèle","SwissNote : environ CHF 1.50 par procès-verbal","Suivi du solde et alerte personnalisée dans votre espace personnel"],"privacy":"Confidentialité et usage professionnel","privacyTitle":"Gardez la maîtrise de vos données","privacyText":"Les IA proposées sont hébergées en Suisse ou en Europe selon le fournisseur sélectionné. Utilisez des données non anonymisées uniquement avec l’autorisation de votre responsable et conformément aux règles de votre organisation et du fournisseur.","technical":"Informations techniques IA Express","technicalText":"Une plateforme d’assistants IA accessible depuis le navigateur, un espace personnel pour suivre la consommation et SwissNote pour les procès-verbaux et rapports. Le fournisseur et les possibilités disponibles dépendent de la configuration de votre organisation.","ready":"Testez gratuitement pendant 7 jours","readyText":"CHF 5.– de crédit de consommation offert. L’essai se termine après 7 jours ou à l’épuisement du crédit. Aucun acompte nécessaire pour démarrer. Vous n’êtes pas membre de HR Valais ? Après votre essai, vous pourrez choisir l’accès à la plateforme sans adhésion, à CHF 100.– par année, ou l’adhésion à HR Valais avec accès à la plateforme, à CHF 150.– par année.","footer":"IA Express — IA Solutions Sàrl · Offre HR Valais"}};
const landingCss="#hr-presentation{font-family:Inter,system-ui,sans-serif;color:#22253b;background:#fafafe;width:100%;box-sizing:border-box;text-align:left}#hr-presentation *{box-sizing:border-box}#hr-presentation .wrap{width:100%;max-width:1080px;margin:auto;padding:0 28px}#hr-presentation .nav{display:flex;align-items:center;justify-content:space-between;gap:18px;padding-top:22px;padding-bottom:22px;background:#fff}#hr-presentation .brand{font-weight:850;font-size:25px;letter-spacing:-1px;color:#7545cc}#hr-presentation .tag{font-size:12px;color:#6b7280}#hr-presentation .hero{padding:58px 0;background:linear-gradient(120deg,#f0e7ff,#faf8ff 55%,#eaf2ff)}#hr-presentation .eyebrow{color:#7545cc;font-size:12px;text-transform:uppercase;font-weight:700;letter-spacing:1.2px}#hr-presentation h1{font-size:clamp(30px,4.5vw,49px);line-height:1.13;letter-spacing:-1.6px;font-weight:800;margin:16px 0 20px}#hr-presentation h1 span{color:#7545cc}#hr-presentation p{font-size:15px;line-height:1.7;color:#5c6277;margin:10px 0 18px}#hr-presentation .intro{max-width:680px;font-size:17px}#hr-presentation .chips{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0}#hr-presentation .chip{font-size:12px;border:1px solid #e7def4;background:#fff;border-radius:30px;padding:9px 12px}#hr-presentation .cta{display:inline-block;text-decoration:none;background:#7545cc;color:#fff;padding:14px 23px;border-radius:9px;font-size:15px;font-weight:650}#hr-presentation a:focus-visible{outline:3px solid #b993ee;outline-offset:4px}#hr-presentation .section{padding:42px 0}#hr-presentation h2{font-size:28px;line-height:1.2;font-weight:750;letter-spacing:-.6px;margin:0 0 12px}#hr-presentation .grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:24px}#hr-presentation .card{background:#fff;border:1px solid #e7e4ee;border-radius:15px;overflow:hidden}#hr-presentation .pad{padding:26px}#hr-presentation .video{aspect-ratio:16/9;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;background:linear-gradient(130deg,#292044,#7450aa);color:#fff;padding:20px;text-align:center}#hr-presentation .video.alt{background:linear-gradient(130deg,#17374e,#588ca5)}#hr-presentation .video strong{font-size:20px}#hr-presentation .video small{font-size:12px;opacity:.8}#hr-presentation .price{font-size:44px;font-weight:800;letter-spacing:-1.4px;margin:15px 0 8px}#hr-presentation .price small{font-size:15px;font-weight:400;color:#6b7280;letter-spacing:0}#hr-presentation ul{padding-left:18px;margin:20px 0 0;color:#535a70;font-size:14px;line-height:1.7}#hr-presentation li{padding:0 0 10px}#hr-presentation li::marker{color:#7545cc}#hr-presentation .privacy{padding:30px;background:#f2eef9;border-radius:15px}#hr-presentation details{border-top:1px solid #ddd4ee;padding-top:18px;margin-top:20px}#hr-presentation summary{cursor:pointer;font-weight:600;color:#5d369e}#hr-presentation .final{background:#281b43;border-radius:17px;padding:36px;text-align:center}#hr-presentation .final h2{color:#fff}#hr-presentation .final p{color:#e3dbef;max-width:700px;margin:16px auto 24px}#hr-presentation .final .cta{background:#fff;color:#6b3db6}#hr-presentation footer{font-size:12px;color:#818398;padding:20px 0 30px}#inscription-hrvalais{scroll-margin-top:32px}@media(max-width:650px){#hr-presentation .wrap{padding-left:18px;padding-right:18px}#hr-presentation .hero{padding:36px 0}#hr-presentation .grid{grid-template-columns:1fr;gap:16px}#hr-presentation .nav{align-items:flex-start;flex-direction:column;gap:6px}#hr-presentation .section{padding:28px 0}#hr-presentation h2{font-size:24px}#hr-presentation .pad,#hr-presentation .privacy,#hr-presentation .final{padding:22px}#hr-presentation .cta{width:100%;text-align:center}}";
const render=function(t){return `<main id="hr-presentation"><style>${landingCss}</style><div class="wrap nav"><div class="brand">IA Express</div><div class="tag">${t.reserved}</div></div><section class="hero"><div class="wrap"><div class="eyebrow">${t.eyebrow}</div><h1>${t.h1}<br><span>${t.h2}</span></h1><p class="intro">${t.intro}</p><div class="chips"><span class="chip">${t.trial}</span><span class="chip">${t.credit}</span><span class="chip">${t.hosting}</span></div><a class="cta" href="#inscription-hrvalais">${t.try}</a></div></section><section class="section"><div class="wrap"><h2>${t.demos}</h2><p>${t.demoIntro}</p><div class="grid"><article class="card"><div class="video"><strong>IA Express</strong><small>${t.video}</small></div><div class="pad"><h3>${t.platform}</h3><p>${t.platformText}</p></div></article><article class="card"><div class="video alt"><strong>SwissNote</strong><small>${t.video}</small></div><div class="pad"><h3>${t.swiss}</h3><p>${t.swissText}</p></div></article></div></div></section><section class="section"><div class="wrap"><h2>${t.pricing}</h2><div class="grid"><article class="card pad"><div class="eyebrow">${t.subscription}</div><div class="price">CHF 10.– <small>${t.month}</small></div><p><strong>${t.quarter}</strong></p><ul>${t.features.map(x=>'<li>'+x+'</li>').join('')}</ul></article><article class="card pad"><div class="eyebrow">${t.usage}</div><h3 style="font-size:24px;margin:16px 0">${t.usageTitle}</h3><p>${t.usageText}</p><ul>${t.costs.map(x=>'<li>'+x+'</li>').join('')}</ul></article></div></div></section><section class="section"><div class="wrap"><div class="privacy"><div class="eyebrow">${t.privacy}</div><h2 style="margin-top:12px">${t.privacyTitle}</h2><p>${t.privacyText}</p><details><summary>${t.technical}</summary><p>${t.technicalText}</p></details></div></div></section><section class="section"><div class="wrap"><div class="final"><h2>${t.ready}</h2><p>${t.readyText}</p><a class="cta" href="#inscription-hrvalais">${t.try}</a></div></div></section><footer class="wrap">${t.footer}</footer></main>`;};
return render(texts[lang]||texts.fr);

